options.a:
def main(target_num, list_num):
	output = []
	for i1 in list_num:
		for i2 in list_num:
			if i1 + i2 == target_num:
				output.append((i1, i2))
	return output

options.b:
def main(target_num,list_num):
	result = []
	for numb in range(target_num//2+1):
		if numb in list_num and target_num-numb in list_num:
			result.append((numb,target_num-numb))
	return result

exam_questions.code_context:
class Flight:
    def __init__(self, airline, origin, destination, capacity=300):
        self.airline = airline
        self.origin = origin
        self.destination = destination
        self.capacity = capacity

    def set_date(self, date):
        self.date = date

class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author
        self.review_scores = []

    def add_review(self, score):
        self.review_scores.append(score)

    def num_reviews(self):
        return len(self.review_scores)

    def average_score(self):
        if self.num_reviews() > 0:
            return sum(self.review_scores) / len(self.review_scores)

options.a:
def compare(self, other):
    avg_better = self.average_score() > other.average_score()
    no_fewer_reviews = self.num_reviews() >= other.num_reviews()
    if avg_better and no_fewer_reviews:
        return self.title
    elif not avg_better:
        return other.title
    else:
        return None

options.b:
def compare(self, other):
    for first, second in [(self, other), (other, self)]:
        avg_better = first.average_score() > second.average_score()
        no_fewer_reviews = first.num_reviews() >= second.num_reviews()
        if avg_better and no_fewer_reviews:
            return first.title

